    CONSTRAINT "ck_outbox_care_contract" CHECK (((("care_contract_version" = 0) AND ("care_lifecycle_order" IS NULL) AND ("care_delivery_cohort_id" IS NULL)) OR (("care_contract_version" = 1) AND ("aggregate_id" IS NOT NULL) AND ("care_lifecycle_order" = ANY (ARRAY[0, 1])) AND ("care_lifecycle_order" IS NOT NULL) AND (((NOT "delivery_enabled") AND ("care_delivery_cohort_id" IS NULL)) OR ("delivery_enabled" AND ("care_delivery_cohort_id" = "aggregate_id") AND ("care_delivery_cohort_id" IS NOT NULL))) AND ((("care_lifecycle_order" = 0) AND (("routing_key")::"text" = 'prescription.created'::"text")) OR (("care_lifecycle_order" = 1) AND (("routing_key")::"text" = ANY ((ARRAY['prescription.filled'::character varying, 'prescription.dispense.failed'::character varying, 'prescription.cancelled'::character varying, 'prescription.expired'::character varying])::"text"[])))))))
);


