    "updated_at" timestamp with time zone,
    "release_reason" character varying(50),
    "released_at" timestamp with time zone,
    "released_by" "uuid",
    CONSTRAINT "ck_reservation_quantity_positive" CHECK (("quantity" > 0)),
    CONSTRAINT "ck_reservation_release_audit" CHECK ((((("status")::"text" = ANY ((ARRAY['RELEASED'::character varying, 'EXPIRED'::character varying])::"text"[])) AND ("release_reason" IS NOT NULL) AND ("released_at" IS NOT NULL)) OR ((("status")::"text" = ANY ((ARRAY['RESERVED'::character varying, 'FULFILLED'::character varying])::"text"[])) AND ("release_reason" IS NULL) AND ("released_at" IS NULL) AND ("released_by" IS NULL)))),
    CONSTRAINT "ck_reservation_release_reason" CHECK ((("release_reason" IS NULL) OR (("release_reason")::"text" = ANY ((ARRAY['PRESCRIPTION_CANCELLED'::character varying, 'PAYMENT_FAILED'::character varying, 'DISPENSE_FAILED'::character varying, 'ADMIN_OVERRIDE'::character varying, 'TTL_EXPIRED'::character varying, 'LEGACY_MIGRATION'::character varying])::"text"[])))),
    CONSTRAINT "ck_reservation_status" CHECK ((("status")::"text" = ANY ((ARRAY['RESERVED'::character varying, 'FULFILLED'::character varying, 'RELEASED'::character varying, 'EXPIRED'::character varying])::"text"[])))
);


