    CONSTRAINT "outpatient_cancellation_source_source_fingerprint_check" CHECK (("source_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "outpatient_cancellation_source_source_type_check" CHECK ((("source_type")::"text" = ANY ((ARRAY['EXAM'::character varying, 'LAB_TEST'::character varying])::"text"[]))),
    CONSTRAINT "outpatient_cancellation_source_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['PENDING'::character varying, 'APPLIED'::character varying, 'REJECTED'::character varying])::"text"[])))
